#!/bin/sh
# runk.sh - one invocation of a K2/K3/K3s/K4 class in a throwaway container (the driver's argv entry point).
# usage: runk.sh <k2|k3|k3-120|k3s|k4-warm|k4-cold|k4-cold-local> [pad]
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'live-host-measurement-confounds/runk.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'runk.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  echo "usage: runk.sh <k2|k3|k3-120|k3s|k4-warm|k4-cold|k4-cold-local> [pad]"
  echo "       runk.sh --help | --build | --version"
  echo "k2/k3/k3-120   cv scenario B / A daemon block (cvblock.sh; k3 idles 30 s, k3-120 idles 120 s) in the lhmc-bench container on the scratch vault"
  echo "k3s     allocator-churn program (src/k3s.c)"
  echo "k4-*    page-cache reads of var/k4/*: warm (untimed pass first), cold (whole-cache drop via ctl, needs LHMC_AFK=1),"
  echo "        cold-local (drops only the files' own pages)"
  echo "Env: LHMC_PIN cpuset for the measured container (empty = unpinned), LHMC_CV_DIR directory of the cv binary,"
  echo "     AIDLE/BLOAD/BPASS/PASSES scenario shortening (see cvblock.sh)."
  exit 0
fi
set -eu


HERE=$(cd "$(dirname "$0")" && pwd)
case ${1:-} in
  --build|--version) exec "$HERE/ctl" --build ;;
esac
cls=${1:?class}; pad=${2:-0}
V=$HERE/var
PIN=${LHMC_PIN:-}
CVDIR=${LHMC_CV_DIR:-$V/build/pre/target/release}
pinarg=""
[ -z "$PIN" ] || pinarg="--cpuset-cpus $PIN"
run() { # run <image> <extra docker args> -- cmd...
  # shellcheck disable=SC2086
  docker run --rm --cgroup-parent lhmc.slice $pinarg -e "MEASURE_PAD=$pad" "$@"
}
case $cls in
  k2|k3|k3-120)
    scen=A; aidle=30; [ "$cls" != k3-120 ] || aidle=120; [ "$cls" != k2 ] || { scen=B; aidle=20; }
    mkdir -p "$V/blk"
    run -e AIDLE="${AIDLE:-$aidle}" -e BLOAD="${BLOAD:-40}" -e BPASS="${BPASS:-10}" -e PASSES="${PASSES:-3}" \
      -v "$HERE:/lhmc:ro" -v "$CVDIR:/cvbin:ro" -v "$V/scratch:/scratch:ro" -v "$V/blk:/blk" lhmc-bench sh /lhmc/cvblock.sh "$scen" ;;
  k3s) run -v "$V:/v:ro" lhmc-bench /v/k3s --threads 12 --seconds 5 --idle 12 ;;
  k4-warm) run -v "$V/k4:/k4:ro" -v "$V:/v:ro" lhmc-bench sh -c '/v/pagecache /k4/f* >/dev/null; /v/pagecache /k4/f*' ;;
  k4-cold)
    "$HERE/ctl" dropcache
    run -v "$V/k4:/k4:ro" -v "$V:/v:ro" lhmc-bench /v/pagecache /k4/f1 /k4/f2 /k4/f3 /k4/f4 ;;
  k4-cold-local) run -v "$V/k4:/k4:ro" -v "$V:/v:ro" lhmc-bench /v/pagecache --evict /k4/f1 /k4/f2 /k4/f3 /k4/f4 ;;
  *) echo "runk.sh: unknown class '$cls' (try --help)" >&2; exit 2 ;;
esac
